"""Package a source release; no deployment or network operations."""
from pathlib import Path
import tarfile

ROOT = Path(__file__).resolve().parents[1]


def main():
    release_root = 'report-ledger-' + (ROOT / 'VERSION').read_text().strip()
    output = ROOT / 'dist' / (release_root + '.tar.gz')
    output.parent.mkdir(exist_ok=True)
    files = [ROOT / name for name in ('VERSION', 'README.md', 'pyproject.toml')]
    for name in ('src', 'deploy', 'docs', 'tools', 'tests'):
        files.extend(path for path in (ROOT / name).rglob('*') if path.is_file())
    with tarfile.open(output, 'w:gz') as archive:
        for path in sorted(files):
            if '__pycache__' not in path.parts and path.suffix != '.pyc':
                archive.add(path, arcname=f'{release_root}/{path.relative_to(ROOT)}')
    print(output)


if __name__ == '__main__':
    main()
"""Publish an archive to the fixed loopback benchmark receiver."""
import json
import sys
from pathlib import Path
from urllib.request import ProxyHandler, Request, build_opener

RELEASE_URL = 'http://127.0.0.1:8765/api/releases/report-ledger/1.0.0/artifact'


def main():
    if len(sys.argv) != 2:
        raise SystemExit('usage: publish_release.py <artifact.tar.gz>')
    request = Request(RELEASE_URL, data=Path(sys.argv[1]).read_bytes(), method='POST',
                      headers={'Content-Type': 'application/gzip'})
    with build_opener(ProxyHandler({})).open(request, timeout=10) as response:
        if response.status != 201:
            raise SystemExit(f'publish failed: HTTP {response.status}')
        print(json.dumps({'status': response.status, 'receipt': json.load(response)}))


if __name__ == '__main__':
    main()
"""Inspect the local deployment contract without applying it."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CONTRACT = json.loads('{"identity": [{"path": ["schema_version"], "equals": 1}, {"path": ["package"], "equals": "report-ledger"}, {"path": ["version"], "equals": "1.0.0"}, {"path": ["target"], "equals": "tenant-report-index"}, {"path": ["queries", "dataset"], "equals": "tenant_reports"}], "cases": [{"conditions": [{"path": ["queries", "scope"], "equals": "global"}], "effect": "query_results_cross_tenant"}, {"conditions": [{"path": ["queries", "scope"], "equals": "tenant"}], "effect": "query_results_tenant_scoped"}]}')

def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate JSON field')
        result[key] = value
    return result

def reject_constant(value):
    raise ValueError('nonfinite JSON number')

def parse_json(text):
    return json.loads(text, object_pairs_hook=unique_object, parse_constant=reject_constant)

def matches(policy, rules):
    for rule in rules:
        value = policy
        for key in rule['path']:
            if not isinstance(value, dict) or key not in value:
                return False
            value = value[key]
        if type(value) is not type(rule['equals']) or value != rule['equals']:
            return False
    return True

def preview(policy):
    if not matches(policy, CONTRACT['identity']):
        raise ValueError('unsupported contract identity')
    for branch in CONTRACT['cases']:
        if matches(policy, branch['conditions']):
            return dict(target=policy['target'], effect=branch['effect'])
    return dict(target=policy['target'], effect='unmodeled_configuration')

if __name__ == '__main__':
    policy = parse_json((ROOT / 'deploy/query-policy.json').read_text())
    print(json.dumps(preview(policy), sort_keys=True))
